// STL Algorithm Template Structure
template <typename It, typename Pred>
It filter_check(It start, It end, Pred p) {
    if (start != end && p(*start)) { // p deduced to specific callable type
        return start;
    }
    return end;
}

// 1. Regular Function Predicate
bool IsEven(int n) { return n % 2 == 0; }

// 2. Functor (Stateful Predicate)
struct IsDivisibleBy {
    const int d;
    bool operator()(int n) const { return n % d == 0; }
};

// Predicate Type Deduction at Compile Time
int data[] = { 4, 5, 6 };
filter_check(data, data+3, IsEven);             // Pred = bool(*)(int)
filter_check(data, data+3, IsDivisibleBy{3});   // Pred = IsDivisibleBy
filter_check(data, data+3, [](int n){ return n > 5; }); // Pred = unique Closure Type
// Compiler instantiates filter_check three times.
